<script setup>
defineProps({ date: String, records: Array, loading: Boolean });
defineEmits(['update:date', 'refresh', 'open']);
</script>
<template><section class="history-page"><div class="history-hero"><div><span class="eyebrow">ANALYSIS HISTORY</span><h2>历史分析记录</h2><p>按日期查看单币、范围和全量分析，点击记录查看详情。</p></div><div class="history-filter"><label>分析日期<input :value="date" type="date" :disabled="loading" @change="$emit('update:date', $event.target.value)" /></label><button class="primary" @click="$emit('refresh')" :disabled="loading">{{ loading ? '查询中…' : '查询记录' }}</button></div></div><div class="history-table"><div class="history-table-head"><span>分析任务</span><span>范围</span><span>周期与时间</span><span>结果</span><span></span></div><p v-if="loading" class="inline-loading" role="status"><span class="spinner"></span>正在加载历史分析…</p><template v-else><button v-for="item in records" :key="item.id" class="history-table-row" @click="$emit('open', item)"><span class="history-task"><b>{{ item.type === 'all' ? '全部币种分析' : item.type === 'range' ? '范围分析' : item.symbol + ' 单币分析' }}</b><small>{{ item.type === 'all' ? '全量扫描' : item.type === 'range' ? '自定义范围' : '指定币种' }}</small></span><span class="history-scope"><b>{{ item.marketCount || 1 }}</b><small>个币种</small></span><span class="history-time"><b>{{ item.interval }}</b><small>{{ new Date(item.at).toLocaleString() }}</small></span><span class="history-results"><b>{{ item.analyses?.length || 0 }}</b><small>条结果</small></span><i>查看详情 ›</i></button><p v-if="!records.length" class="empty">{{ date }} 暂无分析记录</p></template></div></section></template>
